package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Set;
import org.apache.commons.lang.StringUtils;
import org.apache.commons.lang.Validate;
import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_append_TriageGen1Test {

    @Test
    public void testAppend_NullHtml() {
        // given
        Element element = new Element(Tag.valueOf("div"), "https://example.com", null);

        // when
        Element result = element.append(null);

        // then
        assertNull(result);
    }

    @Test
    public void testAppend_EmptyHtml() {
        // given
        Element element = new Element(Tag.valueOf("div"), "https://example.com", null);

        // when
        Element result = element.append("");

        // then
        assertNotNull(result);
        assertEquals(0, result.childNodes().size());
    }

    @Test
    public void testAppend_HtmlWithElements() {
        // given
        Element element = new Element(Tag.valueOf("div"), "https://example.com", null);
        Document doc = Jsoup.parse("<p>Hello</p>");
        Element p = doc.body().appendChild(doc.body().child(0));

        // when
        Element result = element.append(p.outerHtml());

        // then
        assertNotNull(result);
        assertEquals(1, result.childNodes().size());
    }

    @Test
    public void testAppend_HtmlWithoutElements() {
        // given
        Element element = new Element(Tag.valueOf("div"), "https://example.com", null);
        Document doc = Jsoup.parse("<div>Hello</div>");

        // when
        Element result = element.append(doc.body().outerHtml());

        // then
        assertNotNull(result);
        assertEquals(0, result.childNodes().size());
    }

    @Test
    public void testAppend_HtmlWithMultipleElements() {
        // given
        Element element = new Element(Tag.valueOf("div"), "https://example.com", null);
        Document doc = Jsoup.parse("<p>Hello</p><p>World</p>");
        Element p1 = doc.body().child(0);
        Element p2 = doc.body().child(1);

        // when
        Element result = element.append(p1.outerHtml() + p2.outerHtml());

        // then
        assertNotNull(result);
        assertEquals(2, result.childNodes().size());
    }

    @Test
    public void testAppend_HtmlWithTags() {
        // given
        Element element = new Element(Tag.valueOf("div"), "https://example.com", null);
        Document doc = Jsoup.parse("<p>Hello</p>");
        Element p = doc.body().appendChild(doc.body().child(0));

        // when
        Element result = element.append("<p>Hello</p>");

        // then
        assertNotNull(result);
        assertEquals(1, result.childNodes().size());
    }

    @Test
    public void testAppend_HtmlWithoutTags() {
        // given
        Element element = new Element(Tag.valueOf("div"), "https://example.com", null);
        Document doc = Jsoup.parse("<div>Hello</div>");

        // when
        Element result = element.append("Hello");

        // then
        assertNotNull(result);
        assertEquals(0, result.childNodes().size());
    }

    @Test
    public void testAppend_HtmlWithAttributes() {
        // given
        Element element = new Element(Tag.valueOf("div"), "https://example.com", null);
        Document doc = Jsoup.parse("<p id=\"hello\">Hello</p>");
        Element p = doc.body().appendChild(doc.body().child(0));

        // when
        Element result = element.append(p.outerHtml());

        // then
        assertNotNull(result);
        assertEquals(1, result.childNodes().size());
    }

    @Test
    public void testAppend_HtmlWithoutAttributes() {
        // given
        Element element = new Element(Tag.valueOf("div"), "https://example.com", null);
        Document doc = Jsoup.parse("<p>Hello</p>");

        // when
        Element result = element.append(doc.body().outerHtml());

        // then
        assertNotNull(result);
        assertEquals(0, result.childNodes().size());
    }

    @Test
    public void testAppend_HtmlWithStyles() {
        // given
        Element element = new Element(Tag.valueOf("div"), "https://example.com", null);
        Document doc = Jsoup.parse("<p style=\"color: red;\">Hello</p>");
        Element p = doc.body().appendChild(doc.body().child(0));

        // when
        Element result = element.append(p.outerHtml());

        // then
        assertNotNull(result);
        assertEquals(1, result.childNodes().size());
    }

    @Test
    public void testAppend_HtmlWithoutStyles() {
        // given
        Element element = new Element(Tag.valueOf("div"), "https://example.com", null);
        Document doc = Jsoup.parse("<p>Hello</p>");

        // when
        Element result = element.append(doc.body().outerHtml());

        // then
        assertNotNull(result);
        assertEquals(0, result.childNodes().size());
    }
}
